-- Tested with the selected poster seed on an isolated Neon branch before main.
-- Keep imported picture_url values intact: they describe the upstream release.
CREATE TABLE IF NOT EXISTS catalog.artwork_assets (
    anime_id integer PRIMARY KEY REFERENCES catalog.anime(id),
    release_id integer NOT NULL,
    bucket text NOT NULL CHECK (bucket = 'animasters'),
    object_path text NOT NULL UNIQUE,
    public_url text NOT NULL UNIQUE CHECK (
        public_url LIKE 'https://dszqiegiplfnrnovpqvn.supabase.co/storage/v1/object/public/animasters/%'
    ),
    source_url text NOT NULL,
    sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
    byte_size integer NOT NULL CHECK (byte_size > 0),
    content_type text NOT NULL CHECK (content_type IN ('image/jpeg', 'image/png', 'image/webp')),
    width integer NOT NULL CHECK (width > 0),
    height integer NOT NULL CHECK (height > 0),
    stored_at timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (release_id, anime_id) REFERENCES catalog.releases(id, anime_id)
);
-- statement-breakpoint
CREATE INDEX IF NOT EXISTS artwork_assets_release_anime_idx
    ON catalog.artwork_assets (release_id, anime_id);
-- statement-breakpoint
