bff0c106244ceca38b1ae96", "byte_size": 603715, "content_type": "image/jpeg", "width": 2872, "height": 4096, "source_url": "https://media.kitsu.app/anime/poster_images/43321/original.jpg", "public_url": "https://dszqiegiplfnrnovpqvn.supabase.co/storage/v1/object/public/animasters/Tokyo%20Revengers/artwork/cover-64-ba3ee33ed4a6358f6abc9ad287fca7a6a97832325bff0c106244ceca38b1ae96.jpg", "bucket": "animasters"}, {"anime_id": 65, "title": "Vinland Saga", "release_id": 21816, "object_path": "Vinland Saga/artwork/cover-65-ab783ef1f75381d64ea8c396a9d6d2d66f4cd4bc003f6fd2ec94157b0e27a30f.jpg", "sha256": "ab783ef1f75381d64ea8c396a9d6d2d66f4cd4bc003f6fd2ec94157b0e27a30f", "byte_size": 446727, "content_type": "image/jpeg", "width": 1475, "height": 2081, "source_url": "https://static.tvmaze.com/uploads/images/original_untouched/398/995697.jpg", "public_url": "https://dszqiegiplfnrnovpqvn.supabase.co/storage/v1/object/public/animasters/Vinland%20Saga/artwork/cover-65-ab783ef1f75381d64ea8c396a9d6d2d66f4cd4bc003f6fd2ec94157b0e27a30f.jpg", "bucket": "animasters"}, {"anime_id": 66, "title": "Your Lie in April", "release_id": 15187, "object_path": "Your Lie in April/artwork/cover-66-bf1b6a44f83926d319552018aa07d6f53751517ade43a497293d30fe3884a340.jpg", "sha256": "bf1b6a44f83926d319552018aa07d6f53751517ade43a497293d30fe3884a340", "byte_size": 2157477, "content_type": "image/jpeg", "width": 1700, "height": 2451, "source_url": "https://media.kitsu.app/anime/poster_images/8403/original.jpg", "public_url": "https://dszqiegiplfnrnovpqvn.supabase.co/storage/v1/object/public/animasters/Your%20Lie%20in%20April/artwork/cover-66-bf1b6a44f83926d319552018aa07d6f53751517ade43a497293d30fe3884a340.jpg", "bucket": "animasters"}, {"anime_id": 67, "title": "Yu-gi-oh!", "release_id": 28909, "object_path": "Yu-Gi-Oh!/artwork/cover-67-51431fcc13ce2830dda23a0ca86e4f69284106e6b4c379cf3ffe8c6eb429e108.webp", "sha256": "51431fcc13ce2830dda23a0ca86e4f69284106e6b4c379cf3ffe8c6eb429e108", "byte_size": 185908, "content_type": "image/webp", "width": 1024, "height": 1475, "source_url": "https://static.zerochan.net/Yu-Gi-Oh%21.Duel.Monsters.1024.4349688.webp", "public_url": "https://dszqiegiplfnrnovpqvn.supabase.co/storage/v1/object/public/animasters/Yu-Gi-Oh%21/artwork/cover-67-51431fcc13ce2830dda23a0ca86e4f69284106e6b4c379cf3ffe8c6eb429e108.webp", "bucket": "animasters"}]'::jsonb) AS poster (
    anime_id integer, title text, release_id integer, bucket text,
    object_path text, public_url text, source_url text, sha256 text,
    byte_size integer, content_type text, width integer, height integer
);
-- statement-breakpoint
DO $validate$
BEGIN
    -- Abort rather than attach a reviewed poster to a changed answer identity.
    IF EXISTS (
        SELECT 1 FROM artwork_import_rows incoming
        LEFT JOIN catalog.anime anime ON anime.id = incoming.anime_id
        LEFT JOIN catalog.artwork selected ON selected.anime_id = incoming.anime_id
        LEFT JOIN catalog.releases release
            ON release.id = incoming.release_id AND release.anime_id = incoming.anime_id
        WHERE anime.title IS DISTINCT FROM incoming.title
           OR selected.representative_release_id IS DISTINCT FROM incoming.release_id
           OR release.id IS NULL
    ) THEN
        RAISE EXCEPTION 'Poster receipt no longer matches catalog identities';
    END IF;

    IF EXISTS (
        SELECT 1 FROM public.songs song
        LEFT JOIN catalog.song_answers answer ON answer.song_id = song.id
        LEFT JOIN artwork_import_rows incoming ON incoming.anime_id = answer.anime_id
        WHERE incoming.anime_id IS NULL
    ) THEN
        RAISE EXCEPTION 'Receipt does not cover every playable song';
    END IF;

    IF (SELECT count(*) FROM artwork_import_rows) <> 67 THEN
        RAISE EXCEPTION 'Unexpected number of poster rows';
    END IF;
END
$validate$;
-- statement-breakpoint
INSERT INTO catalog.artwork_assets (anime_id, release_id, bucket, object_path, public_url, source_url, sha256, byte_size, content_type, width, height)
SELECT anime_id, release_id, bucket, object_path, public_url, source_url, sha256, byte_size, content_type, width, height FROM artwork_import_rows
ON CONFLICT (anime_id) DO NOTHING;
-- statement-breakpoint
DO $verify$
BEGIN
    -- Identical reruns preserve stored_at; conflicting selections need a new migration.
    IF EXISTS (
        SELECT 1 FROM artwork_import_rows incoming
        LEFT JOIN catalog.artwork_assets stored ON stored.anime_id = incoming.anime_id
        WHERE ROW(stored.anime_id, stored.release_id, stored.bucket, stored.object_path, stored.public_url, stored.source_url, stored.sha256, stored.byte_size, stored.content_type, stored.width, stored.height) IS DISTINCT FROM ROW(incoming.anime_id, incoming.release_id, incoming.bucket, incoming.object_path, incoming.public_url, incoming.source_url, incoming.sha256, incoming.byte_size, incoming.content_type, incoming.width, incoming.height)
    ) THEN
        RAISE EXCEPTION 'Stored artwork differs from the verified selection';
    END IF;
END
$verify$;
